export function characterArt(type='ghost',className=''){if(type==='trump'){const wrap=document.createElement('span');wrap.className=`creature-art trump-art ${className}`;const img=document.createElement('img');img.src='./assets/trump-witch.png';img.alt='Exaggerated Trump in a Halloween witch hat, AI-generated parody';img.decoding='async';const fallback=document.createElement('span');fallback.className='trump-art-fallback';fallback.textContent='BRAIN.EXE\nHAS LEFT';fallback.hidden=true;img.addEventListener('error',()=>{img.hidden=true;fallback.hidden=false},{once:true});wrap.append(img,fallback);return wrap}const node=document.createElementNS('http://www.w3.org/2000/svg','svg');node.setAttribute('viewBox','0 0 128 128');node.setAttribute('aria-hidden','true');node.setAttribute('focusable','false');node.setAttribute('class',`creature-art ${className}`);node.innerHTML=art[type]||art.ghost;return node}
export const characterNames={trump:'THE YUGE MEMORY MALFUNCTION',candy:'THE RUNAWAY CANDY',spider:'THE TINY WEB DEVELOPER',ghost:'THE CONTEXT GHOST',pumpkin:'THE PUMPKIN OF DOUBT'};
export function fallbackHaunt(id=''){const hash=[...String(id)].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,0);const choices=[{character:'trump',line:'My memory is tremendous. Unfortunately, it is on vacation.'},{character:'candy',line:'I traded that memory for one suspicious jellybean.'},{character:'spider',line:'Eight legs. Zero clue where I put that fact.'},{character:'ghost',line:'That fact went through a wall. I did not.'},{character:'pumpkin',line:'My head is literally hollow. The receipts are not.'}];return {...choices[hash%choices.length],admission:'I lost track of something you already told me. Here is the record.'}}
